function escapeChar(c){ return '\\^$.*+?()|[]{}'.indexOf(c)>=0 ? '\\'+c : c; }
function escapeLiteral(s){ var o=''; for(var i=0;i<s.length;i++) o+=escapeChar(s[i]); return o; }
function globToRegExp(glob, opts){
  opts=opts||{};
  var g=String(glob), re='', i=0, n=g.length;
  while(i<n){
    var c=g[i];
    if(c==='*'){
      if(g[i+1]==='*'){
        if(g[i+2]==='/'){ re+='(?:.*/)?'; i+=3; continue; }
        re+='.*'; i+=2; continue;
      }
      re+='[^/]*'; i++; continue;
    }
    if(c==='?'){ re+='[^/]'; i++; continue; }
    if(c==='['){
      var j=i+1, cls='[';
      if(g[j]==='!'){ cls+='^'; j++; }
      while(j<n && g[j]!==']'){
        var cc=g[j];
        if('\\^$.*+?()|{}'.indexOf(cc)>=0 && cc!=='-') cls+='\\'+cc; else cls+=cc;
        j++;
      }
      cls+=']'; re+=cls; i=j+1; continue;
    }
    if(c==='{'){
      var k=i+1, parts=[], cur='';
      while(k<n && g[k]!=='}'){ if(g[k]===','){ parts.push(cur); cur=''; } else cur+=g[k]; k++; }
      parts.push(cur);
      re+='(?:'+parts.map(function(p){ return escapeLiteral(p); }).join('|')+')';
      i=k+1; continue;
    }
    re+=escapeChar(c); i++;
  }
  return new RegExp('^'+re+'$', opts.nocase?'i':'');
}
function isMatch(pathStr, glob, opts){ return globToRegExp(glob,opts).test(String(pathStr)); }
function filter(paths, glob, opts){
  var re=globToRegExp(glob,opts);
  return paths.filter(function(p){ return re.test(String(p)); });
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { globToRegExp:globToRegExp, isMatch:isMatch, filter:filter };
}
if (typeof window !== 'undefined') {
  window.GlobForgePure = { globToRegExp:globToRegExp, isMatch:isMatch, filter:filter };
}
